import {requireStaff,loadWorkspace,saveWorkspace,logout,updatePassword,updateMyProfile,listStaff,setStaffActive,createStaffUser,saveGalleryPhotos} from './backend.mjs';
import {recommendationTemplate,renderWording,drawDocument} from './document-template.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let staff,workspace;
try { staff=await requireStaff();workspace=await loadWorkspace(); }
catch(error){
 const message=String(error.message).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 document.body.innerHTML=`<main style="margin:0;display:grid;min-height:100vh;place-items:center;padding:30px"><section style="max-width:560px;padding:35px;background:white;border-radius:16px;text-align:center"><h1>Staff workspace</h1><p>${message}</p><p>Shared records and staff accounts must be activated before this workspace can open.</p><a href="login.html">Go to staff login →</a> &nbsp; <a href="./">Public website →</a></section></main>`;throw error;
}
let students=workspace.students,docs=workspace.documents,revision=workspace.revision,page='Overview',query='',staffMembers=[],staffMembersLoaded=false;
const types=['Transcript','Recommendation letter','Diploma'];
function safeAvatar(value){const s=String(value||'');return /^(data:image\/(?:jpeg|png|webp);base64,[a-zA-Z0-9+/=]+|https:\/\/[^\s<>"']+)$/.test(s)?s:''}
function renderStaffHeader(){const name=staff.display_name||staff.user?.email||'School office',role=staff.role==='admin'?'School administrator':'Academic administration',avatar=safeAvatar(staff.avatar_url);if($('#staffName'))$('#staffName').textContent=name;if($('#staffRole'))$('#staffRole').textContent=role;if($('#staffAvatar')){const node=$('#staffAvatar');node.textContent=avatar?'':name.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();node.style.backgroundImage=avatar?`url("${avatar}")`:'';node.style.backgroundSize='cover';node.style.backgroundPosition='center';if(node.setAttribute)node.setAttribute('aria-label',name)} }
renderStaffHeader();
async function save(){try{revision=await saveWorkspace(students,docs,revision);}catch(error){modal(`<h2>Changes could not be saved</h2><p>${esc(error.message)}</p><p>Your current changes are still open in this browser tab. Export a copy before reloading.</p><div class="modal-actions"><button onclick="exportUnsaved()">Export unsaved copy</button><button onclick="location.reload()">Reload shared records</button><button onclick="closeModal()">Keep editing</button></div>`);throw error;}}
window.exportUnsaved=()=>{const blob=new Blob([JSON.stringify({students,documents:docs},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cmfi-unsaved-records.json';a.click();URL.revokeObjectURL(url)};
window.staffLogout=logout;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)}function modal(html){$('#overlay').innerHTML=`<div class="modal-wrap"><div class="modal">${html}</div></div>`}window.closeModal=()=>$('#overlay').innerHTML='';
let tablePage=1,genderFilter='',statusFilter='';
const iconPaths={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',students:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a5 5 0 0 1 10 0v4M16 4a3 3 0 0 1 0 6m1 4a5 5 0 0 1 4 5v2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',file:'<path d="M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zM14 3v6h6M8 13h8m-8 4h6"/>',qr:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><path d="M15 15h3v3h3v3h-6v-3m6-6v3M3 12h2m5 0h3v3m-1-8v2m0 9v3"/>',settings:'<path d="m9 3-.7 3-2 .9L3.6 6l-2 3.5L4 12l-.1 2-2.2 2.5 2 3.5 2.7-.9 1.9 1 .7 2.9h4l.7-2.9 1.9-1 2.7.9 2-3.5-2.2-2.5-.1-2 2.4-2.5-2-3.5-2.7.9-2-.9L13 3z" transform="translate(1 -1) scale(.95)"/><circle cx="12" cy="12" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',photo:'<rect x="3" y="4" width="18" height="16" rx="3"/><circle cx="8" cy="9" r="1.5"/><path d="m3 17 5-5 4 4 4-5 5 6"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',letter:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',diploma:'<path d="m2 8 10-5 10 5-10 5zM6 10v6c4 3 8 3 12 0v-6m4-2v9"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconPaths[name]||iconPaths.file}</svg>`}
const pct=(n,total)=>total?Math.round(n/total*100):0;
const isStudentVerified=s=>s.identityVerified===true;
const studentReviewBadge=s=>isStudentVerified(s)?'<span class="badge">● Verified</span>':'<span class="badge amber">● Needs review</span>';
function dashboard(){
 const photos=students.filter(s=>s.photo).length,approved=students.filter(s=>s.status==='Approved').length,gender=students.filter(s=>s.gender==='Male'||s.gender==='Female').length,grades=students.filter(s=>s.subjects?.length).length,total=students.length,coverage=pct(photos,total);
 const stats=[['Total students',total,'Across all student records','students'],['Documents created',docs.length,'Saved in the shared register','file'],['Needs identity review',students.filter(s=>!isStudentVerified(s)).length,'Student identities to verify','clock'],['Student portraits',photos,'Matched graduation photos','photo']];
 const progress=[['Gender recorded',gender],['Student photo',photos],['Grades entered',grades],['Identity verified',students.filter(s=>isStudentVerified(s)).length],['Records approved',approved]];
 const recent=students.filter(s=>s.photo).slice(0,5);
 return `${students.length?'':`<div class="notice" style="margin-bottom:22px">The shared workspace is empty. <button class="textbtn" onclick="importRoster()">Import the 177-student school roster →</button></div>`}<div class="stats">${stats.map(([label,value,caption,key])=>`<div class="stat"><div class="stat-icon">${icon(key)}</div><div><div class="stat-label">${label}</div><strong>${value.toLocaleString()}</strong><small>${caption}</small></div></div>`).join('')}</div><div class="dashboard-grid"><div><div class="panel"><div class="panel-head"><div><h2>Student record overview</h2><div class="sub">A little clarity for every academic journey.</div></div><span class="mini-label">2026 roster</span></div><div class="analytics-content"><div><div class="section-label">STUDENT PHOTO COVERAGE</div><div class="ring-wrap"><div class="coverage-ring"><svg viewBox="0 0 140 140" role="img" aria-label="${coverage}% of students have a photo"><circle cx="70" cy="70" r="58" fill="none" stroke="#f1edf9" stroke-width="13"/><circle cx="70" cy="70" r="58" fill="none" stroke="#ff936c" stroke-width="13" stroke-linecap="round" stroke-dasharray="${coverage*3.644} 364.4"/></svg><div class="ring-center"><strong>${coverage}%</strong><small>with a portrait</small></div></div><div class="legend"><div><i></i>With photo <strong>${photos}</strong></div><div><i class="pale"></i>To complete <strong>${total-photos}</strong></div></div></div></div><div><div class="section-label">RECORD COMPLETENESS</div>${progress.map(([label,value])=>`<div class="progress-item"><div class="progress-label"><span>${label}</span><strong>${value} / ${total}</strong></div><div class="track"><span style="width:${pct(value,total)}%"></span></div></div>`).join('')}</div></div><div class="analytics-note">${icon('info')}Based on the shared school database. Staff changes are saved across devices.</div></div><div class="quick-docs">${types.map((type,i)=>`<button class="quick-doc" onclick="generate('${type}')"><div class="doc-icon">${icon(['file','letter','diploma'][i])}</div><strong>${type} <span style="float:right;color:#b8a9d3">↗</span></strong><small>${['A complete academic record','A personal academic reference','A milestone, beautifully recorded'][i]}</small></button>`).join('')}</div>${studentTable(true)}</div><div class="dashboard-side"><div class="panel"><div class="panel-head"><h2>Student spotlight</h2><span class="mini-label">2026</span></div>${recent.map(s=>`<div class="recent-student" role="button" tabindex="0" onclick="profile('${s.id}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();profile('${s.id}')}"><img src="${esc(s.photo)}" alt=""><div><strong>${esc(s.name)}</strong><small>${esc(s.id)}</small></div><span class="arrow">↗</span></div>`).join('')}<button class="full-width-link" onclick="go('Students')">View all students →</button></div><div class="panel"><div class="panel-head"><h2>Upload a school report</h2></div>${drop()}</div><div class="panel verify-card"><div class="doc-icon">${icon('qr')}</div><h2>A record you can<br>trace back.</h2><p>Look up a document ID or follow its QR code to review the saved record.</p><button class="primary" onclick="go('Verification')">Verify a document &nbsp; ↗</button></div></div></div><div class="footer-note"><span>CMFI Bilingual High School · Academic administration</span><span>Shared academic records.</span></div>`;
}
function render(){
 const items=[['Overview','Dashboard','dashboard'],['Students','Students','students'],['Report uploads','Report uploads','upload'],['Photo uploads','Photo uploads','photo'],['Documents','Documents','file'],['Verification','Verification','qr'],['Settings','Settings','settings']];
 $('#nav').innerHTML=items.map(([n,label,key])=>`<button class="${page===n?'active':''}" ${page===n?'aria-current="page"':''} onclick="go('${n}')"><span>${icon(key)}</span>${label}${n==='Students'?`<b class="nav-count">${students.length}</b>`:''}</button>`).join('');
 $('#breadcrumb').textContent=page==='Overview'?'Dashboard':page;
 const pageActions=page==='Students'?`<button onclick="addStudent()">${icon('plus')} &nbsp; Add student</button>`:page==='Report uploads'?`<button onclick="bulkGrades()">${icon('file')} &nbsp; Bulk WASSCE grades</button><button class="primary" onclick="upload()">${icon('upload')} Upload report</button>`:page==='Photo uploads'?`<button class="primary" onclick="bulkPhotos()">${icon('photo')} Upload photos</button>`:'';
 let h=`<div class="heading"><div><div class="eyebrow">CMFI ACADEMIC WORKSPACE</div><h1>${page==='Overview'?'Every student. Every next chapter.':page}</h1><p>${page==='Overview'?'Welcome to your school’s academic records workspace.':({Students:'The people at the heart of your school.','Report uploads':'A simpler path from school report to student record.','Photo uploads':'Attach graduate portraits to student accounts and publish them to the school website.',Documents:'Create and manage your school’s academic documents.',Verification:'Connect a credential to its saved academic record.',Settings:'A workspace that feels like your school.'}[page])}</p></div>${pageActions?`<div class="actions">${pageActions}</div>`:''}</div>`;
 if(page==='Overview')h+=dashboard();
if(page==='Students')h+=studentTable(false);if(page==='Report uploads')h+=`<div class="panel"><div class="panel-head"><div><h2>Bulk WASSCE grade import</h2><div class="sub">Import a CSV once instead of entering each student one by one.</div></div><button onclick="downloadGradesTemplate()">Download CSV template</button></div><div class="drop" role="button" tabindex="0" onclick="bulkGrades()" ondragover="event.preventDefault()" ondrop="event.preventDefault();importGradesFile(event.dataTransfer.files[0])"><div class="upload-icon">${icon('file')}</div><strong>Drop a WASSCE grades CSV here</strong><p>Use student ID + subject + score columns, or one row per student with subject columns.</p><button class="primary" tabindex="-1">Browse CSV</button></div></div><div class="panel"><div class="panel-head"><h2>Upload an academic report</h2></div>${drop()}<div style="padding:0 23px 23px"><p>Text-based PDF reports are parsed in your browser. Match the student, correct subjects and scores, then approve. Scanned reports require manual entry in this prototype.</p></div></div>${studentTable(false)}`;if(page==='Photo uploads')h+=photoUploadView();
if(page==='Documents')h+=`<div class="actions" style="margin-bottom:22px">${types.map(t=>`<button onclick="generate('${t}')">＋ ${t}</button>`).join('')}<button class="primary" onclick="bulkExport()">⇩ Bulk download PDFs</button></div><div class="panel"><div class="panel-head"><div><h2>Document register</h2><div class="sub">${docs.length} documents · official school templates</div></div><button class="textbtn" onclick="bulkExport()">Bulk export →</button></div>${docs.length?`<div class="table-scroll"><table><thead><tr><th>DOCUMENT</th><th>STUDENT</th><th>ISSUED</th><th>STATUS</th><th></th></tr></thead><tbody>${docs.map(d=>`<tr><td><strong>${esc(d.type)}</strong><div class="sub">${esc(d.id)}</div></td><td>${esc(students.find(s=>s.id===d.student)?.name||'Unknown')}</td><td>${d.date}</td><td><span class="badge ${d.revoked?'amber':''}">${d.revoked?'Revoked':'Active'}</span></td><td><button class="textbtn" onclick="verify('${d.id}')">View</button> <button class="textbtn" onclick="download('${d.id}')">PDF ↓</button> <button class="textbtn" onclick="revoke('${d.id}')">${d.revoked?'Restore':'Revoke'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your document register starts here.<p>Create a document from an approved student record, or use bulk export after grades are approved.</p></div>'}</div>`;
if(page==='Verification')h+=`<div class="panel" style="max-width:760px"><div class="panel-head"><h2>Verify an academic document</h2><span class="badge">QR ENABLED</span></div><div style="padding:30px"><p>Enter the document ID printed beneath its QR code.</p><form onsubmit="event.preventDefault();verify(document.getElementById('verifyId').value)"><input class="search" id="verifyId" placeholder="e.g. SCH-…" required> <button class="primary">Verify document →</button></form><div class="notice">Public verification retrieves the shared document status and automatically opens the associated student page.</div></div></div>`;
if(page==='Settings')h+=settingsView();$('#content').innerHTML=h;if(page==='Settings'&&staff.role==='admin'&&!staffMembersLoaded)refreshStaffMembers(); }
function settingsView(){
 const avatar=safeAvatar(staff.avatar_url),name=staff.display_name||staff.user?.email||'';
 const staffPanel=staff.role==='admin'?`<div class="panel"><div class="panel-head"><div><h2>Staff accounts</h2><div class="sub">Add colleagues, assign roles and disable access when needed.</div></div><button class="primary" onclick="addStaffUser()">${icon('plus')} Add user</button></div><div id="staffAccounts">${staffMembersLoaded?staffAccountsHTML():'<div class="empty">Loading staff accounts…</div>'}</div></div>`:`<div class="panel"><div class="panel-head"><h2>Staff accounts</h2><span class="badge">ADMIN ONLY</span></div><div style="padding:25px"><p>Only an administrator can add, activate or disable staff accounts.</p></div></div>`;
 return `<div class="settings-grid"><div><div class="panel"><div class="panel-head"><div><h2>Institution settings</h2><div class="sub">Shared settings for generated school documents.</div></div><span class="badge">SHARED WORKSPACE</span></div><div style="padding:25px"><label>Institution name<input class="search" id="school" value="${esc(localStorage.getItem('scholar-school')||'CMFI Bilingual High School')}" oninput="this.setCustomValidity('')"></label><p>Used on generated documents.</p><button class="primary" onclick="localStorage.setItem('scholar-school',document.getElementById('school').value);toast('Institution saved')">Save settings</button><p>Student records and documents are saved to the shared database. Documents remain drafts until institutionally approved.</p><p><button onclick="importBrowserRecords()">Import missing records from this browser</button></p></div></div>${staffPanel}</div><div><div class="panel"><div class="panel-head"><div><h2>Your account</h2><div class="sub">Update the name and profile picture shown in the workspace.</div></div><span class="badge">${esc(staff.role||'staff')}</span></div><div style="padding:25px"><form onsubmit="event.preventDefault();saveProfile()"><div class="profile settings-profile">${avatar?`<img id="profileAvatarPreview" src="${esc(avatar)}" alt="Profile picture">`:`<span id="profileAvatarPreview" class="avatar profile-avatar">${esc((name||'?')[0])}</span>`}<div><strong>${esc(staff.user?.email||'')}</strong><p class="sub">Signed-in school account</p></div></div><label>Display name<input id="profileName" class="search" value="${esc(name)}" minlength="2" maxlength="120" required></label><label>Profile picture<input id="profilePhoto" type="file" accept="image/png,image/jpeg,image/webp" onchange="previewProfilePhoto(this)"></label><div class="modal-actions" style="justify-content:flex-start"><button class="primary">Save profile</button></div></form><hr class="settings-rule"><form onsubmit="event.preventDefault();changePassword()"><h3 class="settings-subheading">Change password</h3><label>New password<input id="newPassword" class="search" type="password" minlength="12" autocomplete="new-password" required placeholder="At least 12 characters"></label><label>Confirm password<input id="confirmPassword" class="search" type="password" minlength="12" autocomplete="new-password" required placeholder="Repeat the new password"></label><div class="modal-actions" style="justify-content:flex-start"><button>Update password</button></div></form></div></div></div></div>`;
}
function staffAccountsHTML(){return staffMembers.length?`<div class="staff-list">${staffMembers.map(member=>`<div class="staff-row"><div class="staff-row-avatar">${safeAvatar(member.avatar_url)?`<img src="${esc(safeAvatar(member.avatar_url))}" alt="">`:esc((member.display_name||member.email||'?')[0])}</div><div class="staff-row-main"><strong>${esc(member.display_name||'Unnamed staff')}</strong><small>${esc(member.email||'')} · ${esc(member.role)}</small></div><span class="badge ${member.active?'':'amber'}">${member.active?'Active':'Disabled'}</span>${member.user_id!==staff.user.id?`<button class="textbtn" onclick="toggleStaff('${member.user_id}',${!member.active})">${member.active?'Disable':'Enable'}</button>`:''}</div>`).join('')}</div>`:'<div class="empty">No staff accounts found.</div>'}
async function refreshStaffMembers(){try{staffMembers=await listStaff();staffMembersLoaded=true;if(page==='Settings')render()}catch(error){staffMembersLoaded=true;if(page==='Settings'){$('#staffAccounts').innerHTML=`<div class="notice">${esc(error.message)}</div>`}}}
function drop(){return `<div class="drop" role="button" tabindex="0" onclick="upload()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();upload()}" ondragover="event.preventDefault()" ondrop="event.preventDefault();importPDF(event.dataTransfer.files[0])"><div class="upload-icon">${icon('upload')}</div><strong>Drop a PDF report here</strong><p>We’ll help you review the grades.<br>Selectable-text PDFs · up to 10 MB</p><button class="primary" tabindex="-1">Browse files</button></div>`}
function photoUploadView(){return `<div class="grid"><div><div class="panel"><div class="panel-head"><div><h2>Upload website gallery photos</h2><div class="sub">These images are independent gallery photos and are not matched to student accounts.</div></div><span class="badge">PUBLIC GALLERY</span></div><div class="drop" role="button" tabindex="0" onclick="bulkPhotos()" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();bulkPhotos()}" ondragover="event.preventDefault()" ondrop="event.preventDefault();importGalleryPhotos(event.dataTransfer.files)"><div class="upload-icon">${icon('photo')}</div><strong>Drop gallery photos here</strong><p>Select multiple JPG, PNG or WEBP files. Any filename is accepted, including UUIDs and camera-generated names.</p><button class="primary" tabindex="-1">Choose photos</button></div><div style="padding:0 23px 23px"><div class="notice"><strong>Website publishing</strong><br>Each image is resized and saved as an independent public gallery item. It will not change any student record. View the <a href="graduates.html" target="_blank" rel="noopener">Graduates gallery ↗</a> after uploading.</div><p class="sub">Photos are published in upload order. Keep uploads to 40 images per batch.</p></div></div></div><div><div class="panel"><div class="panel-head"><div><h2>Gallery guidance</h2><div class="sub">Use this area for group photos, graduate portraits and event images.</div></div></div><div style="padding:0 23px 23px"><div class="notice">The original filename is saved as the gallery caption. You can rename photos before uploading if you want cleaner captions.</div><p class="sub">Student account photos remain separate and can still be managed from an individual student record.</p></div></div><div class="panel verify-card"><div class="doc-icon">${icon('photo')}</div><h2>One gallery for<br>your school story.</h2><p>New uploads appear on the public graduate page after the gallery database migration is enabled.</p></div></div></div>`}
function ensureFileInput(id,accept,multiple=false){let input=document.getElementById(id);if(!input){input=document.createElement('input');input.type='file';input.id=id;input.hidden=true;input.accept=accept;input.multiple=multiple;document.body.appendChild(input)}return input}
function csvRows(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i],next=text[i+1];if(ch==='"'&&quoted&&next==='"'){cell+='"';i++;continue}if(ch==='"'){quoted=!quoted;continue}if(ch===','&&!quoted){row.push(cell.trim());cell='';continue}if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&next==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell='';continue}cell+=ch}if(cell||row.length){row.push(cell.trim());if(row.some(Boolean))rows.push(row)}return rows}
const csvKey=value=>String(value||'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_|_$/g,'');
const normalizedName=value=>String(value||'').toUpperCase().replace(/\.[A-Z0-9]+$/i,'').replace(/[_-]+/g,' ').replace(/\b(PHOTO|PORTRAIT|IMAGE|GRADUATE)\b/g,' ').replace(/[^A-Z0-9]+/g,' ').trim().replace(/\s+/g,' ');
function studentForImport(id,name){const cleanId=String(id||'').trim();if(cleanId){const exact=students.find(s=>String(s.id).toLowerCase()===cleanId.toLowerCase());if(exact)return exact;const embedded=students.find(s=>cleanId.toLowerCase().includes(String(s.id).toLowerCase()));if(embedded)return embedded}const cleanName=normalizedName(name);if(!cleanName)return null;return students.find(s=>normalizedName(s.name)===cleanName)||null}
function parseBulkGrades(text){const rows=csvRows(text);if(rows.length<2)throw Error('The CSV needs a header row and at least one student row.');const headers=rows.shift().map(csvKey);const idIndex=headers.findIndex(key=>['id','student_id','student_number','candidate_number','candidate_id','candidate_no'].includes(key));const nameIndex=headers.findIndex(key=>['name','student_name','full_name','student'].includes(key));const subjectIndex=headers.findIndex(key=>['subject','course','paper'].includes(key));const scoreIndex=headers.findIndex(key=>['score','mark','grade','result','percentage','percent'].includes(key));const grouped=new Map(),unmatched=[];for(const row of rows){const id=idIndex>=0?row[idIndex]:'';const name=nameIndex>=0?row[nameIndex]:'';const student=studentForImport(id,name);const entries=[];if(subjectIndex>=0&&scoreIndex>=0){const subject=String(row[subjectIndex]||'').trim();const score=Number.parseFloat(String(row[scoreIndex]||'').replace('%',''));if(subject&&Number.isFinite(score))entries.push([subject,score])}else{headers.forEach((header,index)=>{if(index===idIndex||index===nameIndex||!header||!row[index])return;const score=Number.parseFloat(String(row[index]).replace('%',''));if(Number.isFinite(score))entries.push([header.replace(/_/g,' '),score])})}if(!entries.length)continue;if(!student){unmatched.push({id,name,entries});continue}const existing=grouped.get(student.id)||{student,entries:[]};existing.entries.push(...entries);grouped.set(student.id,existing)}for(const item of grouped.values()){const unique=new Map();for(const [subject,score] of item.entries){if(score<0||score>100)continue;unique.set(normalizedName(subject),[subject,score])}item.entries=[...unique.values()]}return {matched:[...grouped.values()].filter(item=>item.entries.length),unmatched}}
function gradeImportPreview(parsed,fileName){const matchedSubjects=parsed.matched.reduce((sum,item)=>sum+item.entries.length,0);const unmatchedText=parsed.unmatched.length?`<div class="notice"><strong>${parsed.unmatched.length} row${parsed.unmatched.length===1?'':'s'} could not be matched.</strong> Check the student ID/name in the CSV and import them separately.<div class="sub" style="margin-top:8px">${parsed.unmatched.slice(0,8).map(item=>esc(item.id||item.name||'Unnamed row')).join(' · ')}${parsed.unmatched.length>8?' · …':''}</div></div>`:'';modal(`<h2>Review WASSCE grade import</h2><p>${esc(fileName)} contains <strong>${parsed.matched.length}</strong> matched students and <strong>${matchedSubjects}</strong> subject scores.</p>${unmatchedText}<div class="table-scroll"><table><thead><tr><th>STUDENT</th><th>SUBJECTS</th></tr></thead><tbody>${parsed.matched.slice(0,14).map(item=>`<tr><td><strong>${esc(item.student.name)}</strong><div class="sub">${esc(item.student.id)}</div></td><td>${item.entries.map(([subject,score])=>`${esc(subject)} · ${score}`).join('<br>')}</td></tr>`).join('')}${parsed.matched.length>14?`<tr><td colspan="2" class="sub">Showing the first 14 students. All matched rows will be imported.</td></tr>`:''}</tbody></table></div><label style="display:flex;gap:10px;align-items:flex-start;margin-top:18px"><input id="bulkApproveGrades" type="checkbox" style="width:auto;margin-top:4px"> I checked the source report and want to mark these imported records Approved</label><p class="sub">If left unchecked, the grades are saved as Needs review until a staff member verifies them.</p><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="applyBulkGrades">Import matched grades</button></div>`);$('#applyBulkGrades').onclick=async()=>{const approved=$('#bulkApproveGrades').checked;for(const item of parsed.matched){item.student.subjects=item.entries;item.student.status=approved?'Approved':'Review needed';item.student.gradeSource='Bulk WASSCE CSV';item.student.importBatch='wassce-'+new Date().toISOString().slice(0,10)}try{await save();closeModal();render();toast(`${parsed.matched.length} student grade records imported${approved?' and approved':' for review'}`)}catch(error){toast('Grade import could not be saved: '+error.message)}}}
window.importGradesFile=async file=>{if(!file)return;if(!/\.csv$|text\/(csv|plain)/i.test(file.name||file.type))return toast('Choose a CSV or plain-text grade file.');try{const parsed=parseBulkGrades(await file.text());if(!parsed.matched.length)return toast('No rows matched the student IDs or names in the workspace.');gradeImportPreview(parsed,file.name)}catch(error){toast('Grade import failed: '+error.message)}};
window.bulkGrades=()=>{const input=ensureFileInput('wassceCsv','.csv,text/csv,.txt,text/plain');input.value='';input.onchange=()=>{importGradesFile(input.files?.[0]);input.value=''};input.click()};
window.downloadGradesTemplate=()=>{const csv='student_id,student_name,subject,score\n2101772001,ABU KUMBA,Mathematics,82\n2101772001,ABU KUMBA,English Language,76\n';const blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cmfi-wassce-grades-template.csv';a.click();URL.revokeObjectURL(url)};
window.importGalleryPhotos=async files=>{const list=[...(files||[])].filter(file=>/^image\/(jpeg|png|webp)$/i.test(file.type));if(!list.length)return toast('Choose JPG, PNG or WEBP gallery photos.');if(list.length>40)return toast('Upload no more than 40 gallery photos at a time.');const records=[],failed=[];for(const file of list){try{records.push({filename:file.name,title:file.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ').trim(),image_data:await readAvatar(file)})}catch(error){failed.push(file.name+' ('+error.message+')')}}if(!records.length)return toast('No gallery photos could be prepared.');try{await saveGalleryPhotos(records);render();modal(`<h2>Website gallery photos uploaded</h2><p><strong>${records.length}</strong> independent photo${records.length===1?'':'s'} were uploaded. They were not matched to student accounts.</p>${failed.length?`<div class="notice"><strong>${failed.length} file${failed.length===1?'':'s'} need attention:</strong><div class="sub" style="margin-top:8px">${failed.map(esc).join(' · ')}</div></div>`:'<div class="notice">The photos are ready for the public Graduates gallery.</div>'}<div class="modal-actions"><button class="primary" onclick="closeModal()">Done</button></div>`)}catch(error){toast('Gallery upload failed. Run database/004_gallery_photos.sql in Supabase, then try again. '+error.message)}};
window.bulkPhotos=()=>{const input=ensureFileInput('photoFiles','image/jpeg,image/png,image/webp',true);input.value='';input.onchange=()=>{importGalleryPhotos(input.files);input.value=''};input.click()};
function legacyStudentTable(short){
 const list=students.filter(s=>(s.name+' '+s.id+' '+s.program).toLowerCase().includes(query.toLowerCase())&&(!genderFilter||s.gender===genderFilter)&&(!statusFilter||(statusFilter==='Approved'?s.status==='Approved':s.status!=='Approved')));
 const size=short?6:12,pages=Math.max(1,Math.ceil(list.length/size));tablePage=Math.min(tablePage,pages);const current=short?1:tablePage,offset=(current-1)*size,shown=list.slice(offset,offset+size);
 return `<div class="panel"><div class="panel-head"><div><h2>${short?'Student records':'Student directory'} <span style="font-size:10px;font-weight:400;color:#aaa1bc;margin-left:8px">${students.length} students</span></h2><div class="sub">Your student community, all in one place.</div></div><button class="textbtn" onclick="${short?"go('Students')":"reviewPhotos()"}">${short?'View all →':'13 photo matches to review ↗'}</button></div><div class="table-tools"><input class="search" id="studentSearch" aria-label="Search student directory" placeholder="Search name or candidate number…" value="${esc(query)}" oninput="searchStudents(this)">${short?'':`<select aria-label="Filter students by gender" onchange="filterStudents('gender',this.value)"><option value="">All genders</option>${['Male','Female'].map(g=>`<option ${genderFilter===g?'selected':''}>${g}</option>`).join('')}</select><select aria-label="Filter students by record status" onchange="filterStudents('status',this.value)"><option value="">All records</option><option value="Approved" ${statusFilter==='Approved'?'selected':''}>Approved</option><option value="Review" ${statusFilter==='Review'?'selected':''}>Needs review</option></select>`}<span class="sub" style="margin-left:auto">${list.length} matching records</span></div><div class="table-scroll"><table><thead><tr><th>STUDENT NAME</th><th>GENDER</th><th>PROGRAM</th><th>RECORD STATUS</th><th></th></tr></thead><tbody>${shown.map(s=>`<tr><td><div class="person">${s.photo?`<img src="${esc(s.photo)}" alt="" loading="lazy">`:`<span class="avatar" style="background:#f0eaff;color:#8b73c1">${esc(s.name[0])}</span>`}<div><strong>${esc(s.name)}</strong><small>${esc(s.id)}</small></div></div></td><td><span class="gender-tag">${esc(s.gender||'Not recorded')}</span></td><td>${esc(s.program)}<div class="sub">${s.grade==='Not recorded'?'Class not recorded':esc(s.grade)}</div></td><td><span class="badge ${s.status==='Approved'?'':'amber'}">${s.status==='Approved'?'● Approved':'● Needs review'}</span></td><td><button class="textbtn" aria-label="Open record for ${esc(s.name)}" onclick="profile('${s.id}')">View ↗</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">No students match these filters.<p>Try another name or clear your filters.</p></div></td></tr>'}</tbody></table></div><div class="foot"><span>${list.length?'Showing '+(offset+1)+'–'+(offset+shown.length)+' of '+list.length:'0'} student records</span>${short?'<button class="textbtn" onclick="go(\'Students\')">Open student directory →</button>':`<div class="pagination"><button ${current===1?'disabled':''} aria-label="Previous page" onclick="studentPage(${current-1})">‹</button>${Array.from({length:pages},(_,i)=>i+1).filter(n=>n===1||n===pages||Math.abs(n-current)<=1).map((n,i,a)=>`${i&&n-a[i-1]>1?'<span style="padding:6px">…</span>':''}<button class="${n===current?'current':''}" aria-label="Student page ${n}" ${n===current?'aria-current="page"':''} onclick="studentPage(${n})">${n}</button>`).join('')}<button ${current===pages?'disabled':''} aria-label="Next page" onclick="studentPage(${current+1})">›</button></div>`}</div></div>`;
}
function studentTable(short){
 const html=legacyStudentTable(short);
 return html.replace(/<td><span class="badge(?: amber)?">● (?:Approved|Needs review)<\/span><\/td><td><button class="textbtn" aria-label="Open record for [^"]+" onclick="profile\('([^']+)'\)">View ↗<\/button><\/td>/g,(_,id)=>{const student=students.find(item=>item.id===id)||{};return `<td>${studentReviewBadge(student)}${student.status==='Approved'?'':'<div class="sub">Grades need approval</div>'}</td><td><button class="textbtn" aria-label="Open record for ${esc(student.name)}" onclick="profile('${student.id}')">View ↗</button>${isStudentVerified(student)?'':` <button class="textbtn" onclick="reviewStudent('${student.id}')">Verify</button>`}</td>`});
}
window.searchStudents=e=>{const pos=e.selectionStart;query=e.value;tablePage=1;render();const input=$('#studentSearch');input.focus();input.setSelectionRange(pos,pos)};
window.filterStudents=(key,value)=>{if(key==='gender')genderFilter=value;else statusFilter=value;tablePage=1;render()};
function readAvatar(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');if(file.size>5000000)return reject(new Error('Choose a profile picture under 5 MB.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('The profile picture could not be read.'));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error('Choose a valid JPG, PNG or WEBP image.'));image.onload=()=>{const scale=Math.min(1,512/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};image.src=reader.result};reader.readAsDataURL(file)})}
window.previewProfilePhoto=async input=>{try{const avatar=await readAvatar(input.files?.[0]);window.pendingProfileAvatar=avatar;const preview=$('#profileAvatarPreview');if(preview&&avatar){if(preview.tagName==='IMG')preview.src=avatar;else{preview.outerHTML=`<img id="profileAvatarPreview" class="profile-avatar" src="${avatar}" alt="Profile picture">`}}}catch(error){input.value='';toast(error.message)}};
window.saveProfile=async()=>{const name=$('#profileName')?.value.trim();if(!name||name.length<2)return toast('Enter a display name.');try{const data=await updateMyProfile(name,window.pendingProfileAvatar!==undefined?window.pendingProfileAvatar:staff.avatar_url||'');staff={...staff,display_name:data.display_name,role:data.role,avatar_url:data.avatar_url||''};window.pendingProfileAvatar=undefined;renderStaffHeader();render();toast('Profile saved across the workspace')}catch(error){toast('Profile could not be saved: '+error.message)}};
window.changePassword=async()=>{const first=$('#newPassword')?.value||'',second=$('#confirmPassword')?.value||'';if(first.length<12)return toast('Choose a password with at least 12 characters.');if(first!==second)return toast('The passwords do not match.');try{await updatePassword(first);$('#newPassword').value='';$('#confirmPassword').value='';toast('Password updated successfully')}catch(error){toast(error.message)}};
window.addStaffUser=()=>{modal(`<h2>Add a staff user</h2><p>Create the account in Supabase Auth and give it access to the CMFI workspace. The user should change the temporary password after signing in.</p><form id="staffForm"><div class="fields"><label>Full name<input id="newStaffName" required minlength="2" maxlength="120" placeholder="Teacher or administrator name"></label><label>Email address<input id="newStaffEmail" type="email" required placeholder="name@example.com"></label><label>Initial password<input id="newStaffPassword" type="password" required minlength="12" placeholder="At least 12 characters"></label><label>Workspace role<select id="newStaffRole"><option value="registrar">Registrar</option><option value="admin">Administrator</option></select></label></div><div class="notice">The password is used only to create the account and is not saved in the school records table.</div><div class="modal-actions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Create staff account</button></div></form>`);$('#staffForm').onsubmit=async event=>{event.preventDefault();const name=$('#newStaffName').value.trim(),email=$('#newStaffEmail').value.trim(),password=$('#newStaffPassword').value,role=$('#newStaffRole').value;if(password.length<12)return toast('Choose a password with at least 12 characters.');const submit=event.target.querySelector('button.primary');submit.disabled=true;submit.textContent='Creating account…';try{await createStaffUser(email,password,name,role);closeModal();staffMembersLoaded=false;await refreshStaffMembers();toast('Staff account created. Email confirmation may be required.')}catch(error){submit.disabled=false;submit.textContent='Create staff account';toast('Staff account could not be created: '+error.message)}}};
window.toggleStaff=async(userId,active)=>{try{await setStaffActive(userId,active);staffMembersLoaded=false;await refreshStaffMembers();toast(active?'Staff access enabled':'Staff access disabled')}catch(error){toast('Staff access could not be changed: '+error.message)}};
window.reviewStudent=id=>{const s=students.find(student=>student.id===id);if(!s)return;const avatar=safeAvatar(s.photo);modal(`<h2>${s.identityVerified?'Verified student record':'Review student record'}</h2><div class="profile">${avatar?`<img src="${esc(avatar)}" alt="">`:`<span class="avatar">${esc((s.name||'?')[0])}</span>`}<div><h3>${esc(s.name)}</h3><p>${esc(s.id)} · ${esc(s.program||'Program not recorded')}<br>${esc(s.source||'Source not recorded')}</p></div></div><div class="notice">Confirm the student’s name, candidate number, photo and gender against the school’s source records before marking this identity as verified.</div><label style="display:flex;gap:10px;align-items:flex-start;margin-top:20px"><input id="identityCheck" type="checkbox" ${s.identityVerified?'checked':''} style="width:auto;margin-top:4px"> I verified this student’s identity and candidate number.</label><label>Review note<textarea id="reviewNote" placeholder="Optional note for the school office">${esc(s.reviewNote||'')}</textarea></label><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="saveStudentReview">${s.identityVerified?'Save review':'Verify student'}</button></div>`);$('#saveStudentReview').onclick=async()=>{if(!$('#identityCheck').checked)return toast('Confirm the student identity first.');s.identityVerified=true;s.verifiedBy=staff.user.id;s.verifiedAt=new Date().toISOString();s.reviewNote=$('#reviewNote').value.trim();await save();closeModal();render();toast('Student identity verified and saved')};};
window.studentPage=n=>{tablePage=n;render()};
window.globalSearch=value=>{page='Students';query=value.trim();tablePage=1;genderFilter='';statusFilter='';render()};
window.go=n=>{page=n;query='';tablePage=1;genderFilter='';statusFilter='';render()};window.upload=()=>$('#pdf').click();
window.addStudent=()=>{modal(`<h2>Add a student</h2><p>Create the identity linked to academic documents.</p><form id="studentForm"><div class="fields">${[['name','Full name'],['id','Student ID'],['grade','Class / grade'],['program','Program'],['year','Graduation year']].map(([id,l])=>`<label>${l}<input name="${id}" required ${id==='year'?'type="number" min="1900" max="2100"':''}></label>`).join('')}<label>Gender<select name="gender" required><option value="">Select gender</option><option>Male</option><option>Female</option></select></label><label>Student photo<input name="photo" type="file" accept="image/*"></label></div><div class="modal-actions"><button type="button" onclick="closeModal()">Cancel</button><button class="primary">Create student</button></div></form>`);$('#studentForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),s=Object.fromEntries(['name','id','grade','program','year','gender'].map(k=>[k,f.get(k)]));if(students.some(x=>x.id===s.id))return toast('That student ID already exists');let file=f.get('photo');if(file.size>2000000)return toast('Choose a photo under 2 MB');s.photo=file.size?await readData(file):'';s.subjects=[];s.status='Review needed';students.push(s);await save();closeModal();render();toast('Student added')};};function readData(f){return new Promise(r=>{let a=new FileReader();a.onload=()=>r(a.result);a.readAsDataURL(f)})}
window.profile=id=>{let s=students.find(s=>s.id===id);modal(`<h2>Student record</h2><div class="profile">${s.photo?`<img src="${esc(s.photo)}" alt="Student photo">`:''}<div><h3>${esc(s.name)}</h3><p>${esc(s.id)} · ${esc(s.grade)} · ${esc(s.program)}</p></div></div>${studentReviewBadge(s)}<p>Identity: ${isStudentVerified(s)?"Verified":"Needs review"}</p><p>Gender: ${esc(s.gender||'Not recorded')} <button class="textbtn" onclick="editGender('${s.id}')">Edit gender</button></p><table><thead><tr><th>SUBJECT</th><th>SCORE / 100</th></tr></thead><tbody>${s.subjects.map(([n,g])=>`<tr><td>${esc(n)}</td><td>${g}</td></tr>`).join('')}</tbody></table><div class="modal-actions"><button onclick="closeModal()">Close</button><button onclick="replaceStudentPhoto('${s.id}')">${s.photo?'Replace':'Add'} photo</button><button onclick="editGrades('${s.id}')">Edit grades</button><button onclick="reviewStudent('${s.id}')">Review identity</button><button class="primary" onclick="generate('Transcript','${s.id}')">Create transcript</button></div>`)};
window.replaceStudentPhoto=id=>{const input=ensureFileInput('singlePhoto','image/jpeg,image/png,image/webp');input.value='';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;const s=students.find(item=>item.id===id);try{s.photo=await readAvatar(file);s.photoSource={document:'Staff photo upload',file:file.name,matchedBy:'manual account selection',version:1};await save();closeModal();render();toast('Student photo saved and linked to the account')}catch(error){toast('Photo could not be saved: '+error.message)}input.value=''};input.click()};
window.editGrades=id=>{let s=students.find(s=>s.id===id);review(s.subjects.map(x=>x.join(', ')).join('\n'),id)};
function review(text,id='',file=''){modal(`<h2>Review academic grades</h2><p>${file?'Extracted from '+esc(file)+'. ':''}Confirm each subject and score before approving the record.</p><label>Student<select id="match" class="search" style="width:100%;margin:8px 0 20px">${students.map(s=>`<option value="${esc(s.id)}" ${id===s.id?'selected':''}>${esc(s.name)} · ${esc(s.id)}</option>`).join('')}</select></label><label>Subjects and scores<textarea id="grades" placeholder="Mathematics, 92&#10;English Language, 88">${esc(text)}</textarea></label><p style="font-size:11px">One subject per line: Subject, score. Scores must be between 0 and 100. Correct extraction errors here.</p><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="approve">Approve grades</button></div>`);$('#approve').onclick=async()=>{let rows=$('#grades').value.trim().split('\n').map(l=>{let i=l.lastIndexOf(',');return [l.slice(0,i).trim(),Number(l.slice(i+1))]});if(!rows.length||rows.some(r=>!r[0]||!Number.isFinite(r[1])||r[1]<0||r[1]>100)||$('#grades').value.split('\n').some(l=>!l.includes(',')||!l.split(',').pop().trim()))return toast('Use Subject, score on every line (0–100)');let s=students.find(s=>s.id===$('#match').value);if(!s)return toast('Add a student first');s.subjects=rows;s.status='Approved';await save();closeModal();render();toast('Grades approved and saved')};}
window.importPDF=async file=>{if(!file)return;if(file.type!=='application/pdf'||file.size>10485760)return toast('Select a PDF under 10 MB');toast('Reading report…');try{let pdfjs=await import('https://cdn.jsdelivr.net/npm/pdfjs-dist@4.8.69/build/pdf.min.mjs');pdfjs.GlobalWorkerOptions.workerSrc='https://cdn.jsdelivr.net/npm/pdfjs-dist@4.8.69/build/pdf.worker.min.mjs';let pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;if(pdf.numPages>40)throw Error('Use a report with 40 pages or fewer');let lines=[];for(let p=1;p<=pdf.numPages;p++){let t=await(await pdf.getPage(p)).getTextContent();let line='';for(let x of t.items){line+=x.str+' ';if(x.hasEOL){lines.push(line.trim());line=''}}if(line)lines.push(line.trim())}let matches=lines.map(l=>l.match(/^([A-Za-z][A-Za-z &()/-]{2,60})\s+([0-9]{1,3}(?:\.\d+)?)\s*(?:\/\s*100|%)?$/)).filter(m=>m&&+m[2]<=100).map(m=>m[1].trim()+', '+m[2]);review(matches.join('\n'),'',file.name);if(!matches.length)toast('No clear subject rows found. Enter grades manually.')}catch(e){review('','',file.name);toast('Could not extract this PDF. Enter grades manually.')}};$('#pdf').onchange=e=>{importPDF(e.target.files[0]);e.target.value=''};
window.editGender=id=>{const s=students.find(s=>s.id===id);modal(`<h2>Student gender</h2><p>${esc(s.name)} · Check against the student’s records.</p><select id="genderEdit" class="search"><option value="">Select gender</option>${['Male','Female'].map(g=>`<option ${g===s.gender?'selected':''}>${g}</option>`).join('')}</select><div class="modal-actions"><button onclick="profile('${s.id}')">Cancel</button><button class="primary" id="saveGender">Save</button></div>`);$('#saveGender').onclick=async()=>{if(!$('#genderEdit').value)return toast('Select Male or Female');s.gender=$('#genderEdit').value;s.genderSource='Staff confirmed';await save();profile(id);toast('Gender saved')}};
window.generate=(type,id)=>{
 modal(`<h2>Create ${type.toLowerCase()}</h2><p>CMFI letterhead · Review the student’s gender and wording before generating.</p><div class="fields"><label>Student<select id="docStudent">${students.map(s=>`<option value="${esc(s.id)}" ${id===s.id?'selected':''}>${esc(s.name)} · ${s.status}</option>`).join('')}</select></label><label>Issue date<input id="issue" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Student gender<select id="docGender"><option value="">Select gender</option><option>Male</option><option>Female</option></select></label><label style="align-self:center"><input id="genderConfirmed" type="checkbox" style="display:inline;width:auto"> I checked this student’s gender</label></div>${type==='Recommendation letter'?`<label>Recommendation template<textarea id="letter">${esc(recommendationTemplate)}</textarea></label><p style="font-size:11px">Use {{name}}, {{subject}}, {{Subject}}, {{object}} and {{possessive}} for automatic wording. For example, {{Subject}} becomes He or She.</p><div class="notice" id="letterPreview" style="white-space:pre-wrap"></div>`:''}<div class="notice">Draft document. Confirm the academic record and wording before institutional approval. Existing saved documents retain their original wording.</div><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="createDoc">Generate PDF</button></div>`);
 const selected=()=>students.find(s=>s.id===$('#docStudent').value);
 const preview=()=>{if(!$('#letterPreview'))return;try{$('#letterPreview').textContent=renderWording($('#letter').value,{...selected(),gender:$('#docGender').value})}catch(e){$('#letterPreview').textContent=e.message}};
 const change=()=>{$('#docGender').value=selected()?.gender||'';$('#genderConfirmed').checked=false;preview()};
 $('#docStudent').onchange=change;$('#docGender').onchange=()=>{$('#genderConfirmed').checked=false;preview()};if($('#letter'))$('#letter').oninput=preview;change();
 $('#createDoc').onclick=async()=>{const s=selected();if(!s||s.status!=='Approved'||!s.subjects.length)return toast('Approve this student’s grades first');if(!$('#issue').value)return toast('Choose an issue date');if(!$('#docGender').value||!$('#genderConfirmed').checked)return toast('Check and confirm this student’s gender');
 let letter;try{letter=type==='Recommendation letter'?renderWording($('#letter').value,{...s,gender:$('#docGender').value}):undefined}catch(e){return toast(e.message)}
 s.gender=$('#docGender').value;s.genderSource='Staff confirmed';const d={id:'SCH-'+crypto.randomUUID().toUpperCase(),student:s.id,type,date:$('#issue').value,letter,revoked:false,snapshot:JSON.parse(JSON.stringify(s)),institution:'CMFI Bilingual High School',templateVersion:'cmfi-gender-v1'};docs.unshift(d);await save();closeModal();go('Documents');await download(d.id)};
};
function verifyURL(d){return new URL('./student.html?document='+encodeURIComponent(d.id),location.href).href}
async function loadAsset(path){const response=await fetch(path);if(!response.ok)throw Error(path+' could not be loaded');return readData(await response.blob())}
function qrFor(d){if(!window.qrcode)return '';const code=window.qrcode(0,'M');code.addData(verifyURL(d));code.make();return code.createDataURL(4,4)}
function safeFileName(value){return String(value||'student').replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'student'}
async function createPdfBlob(d,assets){
 const snapshot=d.snapshot||students.find(s=>s.id===d.student);if(!snapshot)throw Error('Student record not found');
 const options={...assets,qr:qrFor(d)};
 const pdf=d.type==='Diploma'?new window.jspdf.jsPDF({orientation:'landscape',unit:'mm',format:'a4',compress:true}):new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});
 drawDocument(pdf,{...d,snapshot},options);return pdf.output('blob');
}
window.download=async id=>{const d=docs.find(d=>d.id===id);if(!d)return;if(!window.jspdf)return toast('PDF library unavailable. Reload with internet access.');try{
 const [letterhead,officialPage,diplomaTemplate]=await Promise.all([loadAsset('./cmfi-letterhead.png'),loadAsset('./official-school-letterhead-web.jpg'),loadAsset('./official-diploma-template-web.jpg')]);
 const blob=await createPdfBlob(d,{letterhead,officialPage,diplomaTemplate});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=safeFileName(d.snapshot?.name||d.student)+'-'+d.type.toLowerCase().replace(/[^a-z]+/g,'-')+'.pdf';a.click();URL.revokeObjectURL(url);toast('PDF downloaded from the official school template');
}catch(e){toast('PDF generation failed: '+e.message)}};
window.bulkExport=()=>{
 const eligible=students.filter(s=>s.status==='Approved');
 const transcriptReady=eligible.filter(s=>Array.isArray(s.subjects)&&s.subjects.length).length;
 const recommendationReady=eligible.filter(s=>s.gender==='Male'||s.gender==='Female').length;
 modal(`<h2>Bulk document download</h2><p>Create a ZIP of personalized PDFs using the official CMFI school letterhead and diploma artwork. Only approved student records are included.</p><div class="notice"><strong>${eligible.length}</strong> approved students · <strong>${transcriptReady}</strong> with grades · <strong>${recommendationReady}</strong> with confirmed gender</div><div class="fields" style="margin-bottom:8px"><label><input id="bulkTranscript" type="checkbox" checked style="display:inline;width:auto;margin-right:8px"> Official transcripts <span class="sub">${transcriptReady} ready</span></label><label><input id="bulkRecommendation" type="checkbox" checked style="display:inline;width:auto;margin-right:8px"> Recommendation letters <span class="sub">${recommendationReady} ready</span></label><label><input id="bulkDiploma" type="checkbox" checked style="display:inline;width:auto;margin-right:8px"> Diplomas <span class="sub">${eligible.length} ready</span></label></div><p class="sub">Each PDF receives a unique document ID and QR code. A verification index is included in the ZIP. Documents still require the school’s authorized signatures before release.</p><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="startBulk">Create ZIP download</button></div>`);
 $('#startBulk').onclick=()=>runBulkExport({transcript:$('#bulkTranscript').checked,recommendation:$('#bulkRecommendation').checked,diploma:$('#bulkDiploma').checked});
};
async function runBulkExport(selection){
 if(!window.jspdf||!window.JSZip)return toast('PDF/ZIP libraries are unavailable. Reload with internet access.');
 const chosen=students.filter(s=>s.status==='Approved');const kinds=[];if(selection.transcript)kinds.push('Transcript');if(selection.recommendation)kinds.push('Recommendation letter');if(selection.diploma)kinds.push('Diploma');
 if(!kinds.length)return toast('Choose at least one document type');
 const candidates=chosen.filter(s=>(!kinds.includes('Transcript')||(Array.isArray(s.subjects)&&s.subjects.length))&&(!kinds.includes('Recommendation letter')||(s.gender==='Male'||s.gender==='Female')));
 if(!candidates.length)return toast('No approved students are ready for the selected documents');
 closeModal();modal(`<h2>Preparing the official ZIP</h2><p id="bulkStatus">Loading the school templates…</p><progress id="bulkBar" value="0" max="100" style="width:100%;height:12px"></progress><p class="sub">Keep this page open while the PDFs are created. You can continue when the download starts.</p>`);
 try{
  const [letterhead,officialPage,diplomaTemplate]=await Promise.all([loadAsset('./cmfi-letterhead.png'),loadAsset('./official-school-letterhead-web.jpg'),loadAsset('./official-diploma-template-web.jpg')]);
  const zip=new window.JSZip();const index=['Student,Student ID,Document type,Document ID,Verification URL'];let created=0,now=new Date().toISOString().slice(0,10),newDocs=[];
  const totalWork=candidates.reduce((total,student)=>total+kinds.filter(type=>(type!=='Transcript'||student.subjects?.length)&&(type!=='Recommendation letter'||student.gender==='Male'||student.gender==='Female')).length,0);
  const updateProgress=(message,done=created)=>{const status=$('#bulkStatus'),bar=$('#bulkBar');if(status)status.textContent=message;if(bar)bar.value=totalWork?Math.round(done/totalWork*100):0};
  updateProgress('Creating personalized PDFs…',0);
  for(const student of candidates){
   for(const type of kinds){
    if(type==='Transcript'&&(!student.subjects||!student.subjects.length))continue;if(type==='Recommendation letter'&&!(student.gender==='Male'||student.gender==='Female'))continue;
    let d=docs.find(existing=>existing.student===student.id&&existing.type===type&&!existing.revoked&&existing.templateVersion==='cmfi-official-v2');
    if(!d){let letter;try{letter=type==='Recommendation letter'?renderWording(recommendationTemplate,student):undefined}catch(error){continue}d={id:'SCH-'+crypto.randomUUID().toUpperCase(),student:student.id,type,date:now,letter,revoked:false,snapshot:JSON.parse(JSON.stringify(student)),institution:'CMFI Bilingual High School',templateVersion:'cmfi-official-v2'};docs.unshift(d);newDocs.push(d)}
    const blob=await createPdfBlob(d,{letterhead,officialPage,diplomaTemplate});zip.file(`${safeFileName(student.name)}/${type.toLowerCase().replace(/[^a-z]+/g,'-')}.pdf`,blob);index.push([student.name,student.id,type,d.id,verifyURL(d)].map(value=>'"'+String(value).replaceAll('"','""')+'"').join(','));created++;
    updateProgress('Creating personalized PDFs · '+created+' of '+totalWork,created);
    if(created%2===0)await new Promise(resolve=>setTimeout(resolve,0));
   }
  }
  if(newDocs.length)await save();zip.file('verification-index.csv',index.join('\n'));zip.file('README.txt','CMFI Bilingual High School\nBulk document export\n\nOnly approved student records are included. Each PDF contains a QR code linking to its public verification page. Documents require authorized school signatures before release.\n');
  updateProgress('Compressing the ZIP for download…',totalWork);const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'},metadata=>{const status=$('#bulkStatus'),bar=$('#bulkBar');if(status)status.textContent='Compressing the ZIP · '+Math.round(metadata.percent)+'%';if(bar)bar.value=metadata.percent});
  const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='cmfi-official-documents-'+now+'.zip';a.click();URL.revokeObjectURL(url);closeModal();render();toast('ZIP download ready · '+created+' PDFs');
 }catch(error){closeModal();toast('Bulk export failed: '+error.message)}
}
window.verify=id=>{const url=new URL('./student.html?document='+encodeURIComponent(id.trim()),location.href);window.open(url.href,'_blank','noopener')};
window.revoke=async id=>{const d=docs.find(d=>d.id===id);d.revoked=!d.revoked;await save();render();toast(d.revoked?'Document revoked in shared records':'Document restored in shared records')};
window.importRoster=async()=>{const response=await fetch('./student-roster.json');if(!response.ok)return toast('Roster unavailable');const roster=await response.json();const ids=new Set(students.map(s=>s.id));students.push(...roster.filter(s=>!ids.has(s.id)));await save();render();toast('School roster imported into shared records')};
window.importBrowserRecords=()=>{let oldStudents,oldDocs;try{oldStudents=JSON.parse(localStorage.getItem('scholar-students')||'[]');oldDocs=JSON.parse(localStorage.getItem('scholar-docs')||'[]');}catch{return toast('The previous browser data could not be read')}
 modal(`<h2>Review previous browser records</h2><p>This browser contains ${oldStudents.length} student records and ${oldDocs.length} documents from the prototype. Only students and documents missing from the shared database will be added. Existing shared records are preserved.</p><div class="modal-actions"><button onclick="closeModal()">Cancel</button><button class="primary" id="importOld">Import missing records</button></div>`);
 $('#importOld').onclick=async()=>{const ids=new Set(students.map(s=>s.id)),docIds=new Set(docs.map(d=>d.id));students.push(...oldStudents.filter(s=>!ids.has(s.id)));docs.push(...oldDocs.filter(d=>!docIds.has(d.id)));await save();closeModal();render();toast('Missing browser records imported')};
};
render();
window.reviewPhotos=async()=>{const response=await fetch('./photo-review.json');const rows=await response.json();modal(`<h2>Photo matches needing confirmation</h2><p>These 13 portraits have caption differences. They have not been attached to accounts. A further 54 roster students have no confirmed portrait in the program.</p><table><thead><tr><th>PROGRAM CAPTION</th><th>REVIEW NOTE</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.caption)}<div class="sub">PDF page ${r.pdfPage}, portrait ${r.position}</div></td><td>${esc(r.reason)}</td></tr>`).join('')}</tbody></table><div class="modal-actions"><button onclick="closeModal()">Close</button></div>`)};
